export class PriorityQueue {
    heap = [];
    parentIndex(index) {
        return Math.floor((index - 1) / 2);
    }
    leftChildIndex(index) {
        return 2 * index + 1;
    }
    rightChildIndex(index) {
        return 2 * index + 2;
    }
    swap(i, j) {
        [this.heap[i], this.heap[j]] = [this.heap[j], this.heap[i]];
    }
    enqueue(item) {
        this.heap.push(item);
        this.heapifyUp();
    }
    dequeue() {
        if (this.heap.length === 0)
            return undefined;
        if (this.heap.length === 1)
            return this.heap.pop();
        const root = this.heap[0];
        this.heap[0] = this.heap.pop();
        this.heapifyDown();
        return root;
    }
    peek() {
        return this.heap[0];
    }
    heapifyUp() {
        let index = this.heap.length - 1;
        while (index > 0 &&
            this.heap[this.parentIndex(index)].priority > this.heap[index].priority) {
            this.swap(index, this.parentIndex(index));
            index = this.parentIndex(index);
        }
    }
    heapifyDown() {
        let index = 0;
        while (this.leftChildIndex(index) < this.heap.length) {
            let smallerChildIndex = this.leftChildIndex(index);
            if (this.rightChildIndex(index) < this.heap.length &&
                this.heap[this.rightChildIndex(index)].priority <
                    this.heap[smallerChildIndex].priority) {
                smallerChildIndex = this.rightChildIndex(index);
            }
            if (this.heap[index].priority <= this.heap[smallerChildIndex].priority) {
                break;
            }
            this.swap(index, smallerChildIndex);
            index = smallerChildIndex;
        }
    }
    isEmpty() {
        return this.heap.length === 0;
    }
    size() {
        return this.heap.length;
    }
}
